'use strict';
(()=>{
  const API='https://franklin-navigator-membership.onrender.com';
  const PLAN=Object.freeze({monthly:{label:'Monthly Community Membership',price:'$5/month',lookupKey:'franklin_community_member_monthly_v5'},annual:{label:'Annual Community Membership',price:'$50/year',lookupKey:'franklin_community_member_annual_v5'},charter:{label:'Charter Community Membership',price:'$120 for 36 months',lookupKey:'franklin_charter_member_36_month_v5'}});
  const params=new URLSearchParams(location.search),$=(s,r=document)=>r.querySelector(s);
  const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n};
  const button=(text,fn,cls='button primary')=>{const n=el('button',text,cls);n.type='button';n.addEventListener('click',fn);return n};
  const link=(text,href,cls='button')=>{const n=el('a',text,cls);n.href=href;return n};
  const field=(labelText,name,type='text',autocomplete='')=>{const label=el('label');label.append(el('span',labelText));const input=document.createElement('input');input.name=name;input.type=type;if(autocomplete)input.autocomplete=autocomplete;label.append(input);return{label,input}};
  const notice=(text,kind='')=>{const n=el('div',text,`r37-status${kind?' '+kind:''}`);n.setAttribute('role','status');return n};
  const planFor=key=>Object.values(PLAN).find(p=>p.lookupKey===key)||{label:'Community Membership',price:''};
  async function request(path,{method='GET',body}={}){const response=await fetch(API+path,{method,credentials:'include',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});let payload={};try{payload=await response.json()}catch{}if(!response.ok){const e=new Error(payload?.error?.message||'Franklin could not complete this request.');e.code=payload?.error?.code||`HTTP_${response.status}`;e.status=response.status;throw e}return payload}
  const CHECKOUT_PENDING_MESSAGE='We could not confirm the payment outcome. Do not pay again. Check membership status or contact support.';
  const friendlyError=(e,payment=false)=>{if(e?.code==='PROFILE_VERIFICATION_REQUIRED')return'We still need to confirm that you represent this profile before payment can open.';if(e?.code==='MEMBERSHIP_ALREADY_ACTIVE')return'This profile already has an active Community Membership. Do not pay again.';if(e?.code==='COMMERCE_DISABLED')return'Checkout is not open. Check membership status for any earlier payment.';if(payment||['PAYMENT_OUTCOME_UNKNOWN','CHECKOUT_PENDING','CHECKOUT_PLAN_CONFLICT','CHECKOUT_RECOVERY_REQUIRED'].includes(e?.code))return CHECKOUT_PENDING_MESSAGE;return'We could not complete this request. Please try again or contact support.'};
  const pendingKey=state=>{const account=state.me?.account?.accountId||state.me?.account?.account_id||state.me?.account?.id;const profile=state.selected?.i;return account&&profile?'franklin.checkout.pending.v1:'+account+':'+profile:null};
  const isPending=state=>{if(state.purchasePending)return true;try{const key=pendingKey(state);return Boolean(key&&sessionStorage.getItem(key))}catch{return false}};
  const setPending=(state,value)=>{state.purchasePending=value;try{const key=pendingKey(state);if(key){if(value)sessionStorage.setItem(key,'pending');else sessionStorage.removeItem(key)}}catch{}};
  const CHECKOUT_NOT_STARTED=new Set(['COMMERCE_DISABLED','CHECKOUT_INFRASTRUCTURE_NOT_READY','PROFILE_VERIFICATION_REQUIRED','MEMBERSHIP_ALREADY_ACTIVE','PLAN_INVALID','PROFILE_INVALID','AUTH_REQUIRED']);
  async function getMe(){try{return await request('/api/accounts/me')}catch(e){if(e.status===401)return null;throw e}}
  const active=me=>['ACTIVE','ACTIVE_CANCELING','GRACE'].includes(String(me?.membership?.status||''));
  let profiles=null;
  async function loadProfiles(){if(profiles)return profiles;const manifest=await fetch('/data/franklin-profiles-manifest.json').then(r=>r.json());const chunks=await Promise.all(manifest.chunks.map(c=>fetch(c.file).then(r=>r.json())));profiles=chunks.flatMap(c=>c.records).map(r=>({...r,s:`${r.n} ${r.c||''} ${r.g||''} ${r.l||''}`.toLowerCase()}));return profiles}
  async function profileName(id){if(!id)return'';const rows=await loadProfiles();return rows.find(r=>r.i===id)?.n||'Your Franklin profile'}
  function accountSection(state,rerender){const s=el('section',null,'r37-member-step');s.append(el('h2',state.me?'Your account':'Create an account or sign in'));if(state.me){s.append(el('p',`Signed in as ${state.me.account?.email||'your Franklin account'}.`));s.append(button('Sign out',async()=>{try{await request('/api/accounts/logout',{method:'POST',body:{}});state.me=null;state.selected=null;state.purchasePending=false;state.message='Signed out.';rerender()}catch(e){state.message=friendlyError(e);rerender()}},'button'));return s}const tabs=el('div',null,'r37-member-actions'),create=button('Create account',()=>{state.accountMode='register';rerender()},state.accountMode==='register'?'button primary':'button'),sign=button('Sign in',()=>{state.accountMode='login';rerender()},state.accountMode==='login'?'button primary':'button');tabs.append(create,sign);s.append(tabs);const form=document.createElement('form');form.className='r37-member-step';if(state.accountMode==='register'){const name=field('Your name','displayName','text','name'),email=field('Email','email','email','email'),pw=field('Create password (12+ characters)','password','password','new-password');form.append(name.label,email.label,pw.label);const submit=el('button','Create account','button primary');submit.type='submit';form.append(submit);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;try{await request('/api/accounts/register',{method:'POST',body:{displayName:name.input.value,email:email.input.value,password:pw.input.value}});state.me=await getMe();state.message='Your Franklin account is ready.'}catch(err){state.message=friendlyError(err)}rerender()})}else{const email=field('Email','email','email','email'),pw=field('Password','password','password','current-password');form.append(email.label,pw.label);const submit=el('button','Sign in','button primary');submit.type='submit';form.append(submit);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;try{await request('/api/accounts/login',{method:'POST',body:{email:email.input.value,password:pw.input.value}});state.me=await getMe();state.message='Signed in.'}catch(err){state.message=friendlyError(err)}rerender()})}s.append(form);return s}
  function profileSection(state,rerender){const s=el('section',null,'r37-member-step');s.append(el('h2','Find your profile'));s.append(el('p','Search by business, professional practice, organization, category or location, then choose the matching listing.'));const search=el('div',null,'r37-member-search'),f=field('Business, professional or organization','profileSearch','search','organization'),go=button('Search',()=>runSearch());f.input.placeholder='Start typing a name or category';search.append(f.label,go);s.append(search);const results=el('div',null,'r37-search-results');results.setAttribute('aria-live','polite');s.append(results);const runSearch=async()=>{const q=f.input.value.trim().toLowerCase();if(q.length<2){results.textContent='Type at least two characters.';return}results.textContent='Searching Franklin profiles…';try{const rows=(await loadProfiles()).filter(r=>r.s.includes(q)).slice(0,12);results.replaceChildren();if(!rows.length){results.append(el('p','No matching profile found.'));results.append(link('I don’t see my business or organization','/profile-request/'));return}for(const row of rows){const b=button('',()=>select(row),'r37-search-result'),txt=el('span'),strong=el('strong',row.n),small=el('small',[(window.FranklinI18n?.category?.(row.c)||row.c),row.l||row.g].filter(Boolean).join(' · ')),choose=el('span','This is my profile');txt.append(strong,small);b.append(txt,choose);results.append(b)}}catch{results.textContent='Profile search could not load. Please try again.'}};const select=async row=>{state.selected=row;state.message='Profile selected. Confirm your account represents this profile.';try{await request('/api/profile-links',{method:'POST',body:{profileId:row.i}});state.me=await getMe()}catch(e){state.message=friendlyError(e)}rerender()};f.input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runSearch()}});if(state.selected){s.append(notice(`Selected: ${state.selected.n}`,'good'))}const links=state.me?.profileLinks||[];if(links.length){s.append(link('Request or check profile access','/profile-studio/'));const verified=links.find(r=>r.authority_state==='VERIFIED');if(verified&&!state.selected){loadProfiles().then(rows=>{state.selected=rows.find(x=>x.i===verified.profile_id)||null;rerender()})}const verificationMessage=verified?(state.ready?.liveCheckoutEnabled?'Profile verified. You can continue to membership.':'Profile verified. Checkout is not open. Check membership status for any earlier payment.'):'Request profile access to continue. Payment stays closed until your representation is confirmed.';s.append(notice(verificationMessage,verified?'good':'warn'))}return s}
  function membershipSection(state,rerender){const s=el('section',null,'r37-member-step');s.append(el('h2','Community Membership'));if(active(state.me)){const p=planFor(state.me.membership?.lookup_key);s.append(notice('Membership active. Do not make another payment.','good'));const summary=el('div',null,'r37-account-summary');summary.append(summaryItem('Plan',`${p.label}${p.price?' — '+p.price:''}`),summaryItem('Profile',state.profileLabel||'Your connected Franklin profile'),summaryItem('Benefits','Member profile tools, Growth Desk and community participation'),summaryItem('Billing','Managed securely through Stripe'));s.append(summary);const actions=el('div',null,'r37-member-actions');actions.append(link('Use my member benefits','/member-first-value/','button primary'));actions.append(button('Manage or cancel billing',async()=>{try{const result=await request('/api/billing/portal',{method:'POST',body:{}});location.assign(result.url)}catch(e){state.message=friendlyError(e);rerender()}},'button'));actions.append(link('Manage my profile','/profile-studio/'));actions.append(link('Get support','/member-support/'));s.append(actions);return s}const selected=state.selected,linked=selected&&(state.me?.profileLinks||[]).find(r=>r.profile_id===selected.i);if(!selected){s.append(notice('Choose your profile above before selecting a membership.'));return s}if(!linked||linked.authority_state!=='VERIFIED'){s.append(notice('We’re still confirming that you represent this profile. Checkout will appear after the review is complete.','warn'));return s}if(isPending(state)){s.append(notice(CHECKOUT_PENDING_MESSAGE,'warn'));const recovery=el('div',null,'r37-member-actions');recovery.append(button('Check membership status',async()=>{try{state.me=await getMe();if(active(state.me)){setPending(state,false);state.message='Payment confirmed. Membership active.'}else state.message=CHECKOUT_PENDING_MESSAGE}catch{state.message=CHECKOUT_PENDING_MESSAGE}rerender()},'button primary'),link('Get support','/member-support/'));s.append(recovery);return s}if(!state.ready?.liveCheckoutEnabled){s.append(notice('Checkout is not open. Check membership status for any earlier payment.','warn'));return s}s.append(notice('Profile verified. Choose the membership term that fits your organization.','good'));const grid=el('div',null,'r37-plan-grid');for(const [id,p] of Object.entries(PLAN)){const card=el('article',null,`r37-plan${id==='annual'?' recommended':''}`);card.append(el('h3',p.label),el('p',p.price,'r37-plan-price'));if(id==='annual')card.append(el('p','Recommended for simple yearly billing.'));if(id==='charter')card.append(el('p','Prepaid for 36 months. No automatic renewal.'));const pay=button(`Continue with ${p.price}`,async()=>{if(isPending(state))return;setPending(state,true);pay.disabled=true;state.message='Opening secure checkout…';rerender(false);try{const result=await request('/api/membership/start',{method:'POST',body:{profileId:selected.i,lookupKey:p.lookupKey}});const checkout=new URL(result.checkoutUrl);if(checkout.protocol!=='https:'||checkout.host!=='checkout.stripe.com'||checkout.username||checkout.password)throw new Error('Invalid checkout destination');location.assign(checkout.href)}catch(e){if(CHECKOUT_NOT_STARTED.has(e?.code))setPending(state,false);if(e?.code==='COMMERCE_DISABLED')state.ready={...state.ready,liveCheckoutEnabled:false};state.message=friendlyError(e,true);rerender()}},id==='annual'?'button primary':'button');card.append(pay);grid.append(card)}s.append(grid);s.append(el('p','Monthly and annual memberships renew until canceled. Charter is prepaid for 36 months and does not automatically renew. Membership does not buy factual accuracy, ranking, endorsement, credentials, leads or guaranteed results.','fine-print'));return s}
  const summaryItem=(label,value)=>{const n=el('div',null,'r37-summary-item');n.append(el('strong',label),el('span',value));return n};
  async function poll(state,rerender){if(!state.me||params.get('checkout')!=='success')return;state.message='Payment processing — do not pay again.';rerender(false);for(let i=0;i<12;i++){try{await new Promise(r=>setTimeout(r,i?2500:500));state.me=await getMe();if(active(state.me)){state.message='Payment confirmed. Membership active.';rerender();return}}catch{}}state.message='Payment processing — do not pay again. Franklin is still confirming your membership. Refresh shortly or contact member support.';rerender()}
  async function init(root){const state={ready:null,me:null,selected:null,profileLabel:'',accountMode:'register',message:'Checking membership availability…'};const render=()=>{root.replaceChildren();if(state.message)root.append(notice(state.message));if(!state.ready)return;if(active(state.me)){profileName((state.me.profileLinks||[]).find(r=>r.authority_state==='VERIFIED')?.profile_id).then(n=>{if(n&&state.profileLabel!==n){state.profileLabel=n;render()}});root.append(accountSection(state,render),membershipSection(state,render));return}root.append(accountSection(state,render));if(state.me)root.append(profileSection(state,render),membershipSection(state,render))};render();try{state.ready=await request('/ready');state.me=await getMe();state.message=state.ready.liveCheckoutEnabled?'Membership sign-in is available.':'Membership accounts are available; new checkout is currently closed.';const pre=params.get('profile');if(pre){const rows=await loadProfiles();state.selected=rows.find(r=>r.i===pre)||null}render();await poll(state,render)}catch(e){state.ready={ok:false,liveCheckoutEnabled:false};state.message=friendlyError(e);render()}}
  for(const root of document.querySelectorAll('[data-membership-live-root]'))init(root);
})();
